-- Issue #855 Religious Harmony slice 2: holy-site pilgrimages (granted or denied by the custodian) and clergy charity, one per citizen per act per game day. Additive only.
CREATE TABLE IF NOT EXISTS faith_harmony_acts (user_id TEXT NOT NULL REFERENCES citizens(clerk_user_id) ON DELETE CASCADE, act TEXT NOT NULL CHECK(act IN ('pilgrimage','charity')), game_day INTEGER NOT NULL, nation_id TEXT NOT NULL, site_id TEXT, outcome TEXT NOT NULL CHECK(outcome IN ('granted','denied','given')), acted_at INTEGER NOT NULL, request_id TEXT NOT NULL UNIQUE, PRIMARY KEY (user_id, act, game_day));
